INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('luc-maillet', 'Luc Maillet', NULL, 'Vice-Prime Minister of Free Quebec; head of the Executive Council', 'rifts', NULL, '8th level Politician/Leader, 6th level Operator', 8, 'Unprincipled', NULL, NULL, NULL, '{"IQ":14,"MA":18,"PE":17}', 53, 31, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A patriot almost as fervent as Lome, whom he trusts completely; he may second-guess how the Prime Minister goes about things, yet has no doubt Lome acts for Quebec.', NULL, NULL, 'Lome''s running mate, in office as long as he has been, and his chief adviser and go-between. He championed the technology deal with the NGR and Triax and helped draft it. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.143'),
('gerard-dupuis', 'Prince Gerard Dupuis', NULL, 'Prince; official representative of the Kingdom of the Saguenay on the Executive Council', 'rifts', NULL, '7th level Freelance Spy', 7, 'Anarchist with leanings toward Miscreant', NULL, NULL, NULL, '{"IQ":17,"ME":19,"MA":21,"PP":18,"PE":15}', 49, 40, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Son of King Robert Dupuis of the Saguenay, a founding kingdom of the nation, and among the advisers Lome relies on most. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.143'),
('joseph-arsenault', 'Mayor Joseph Arsenault', NULL, 'Mayor of the City of Free Quebec; member of the Executive Council', 'rifts', NULL, '7th level Scholar/Politician', 7, 'Aberrant', NULL, NULL, NULL, '{"IQ":12,"MA":22}', 42, 21, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The capital''s elected mayor, who has earned a place among the Prime Minister''s respected advisers.', 'Rifts World Book 22: Free Quebec p.143'),
('gilles-duseault', 'Gilles Duseault', NULL, 'Minister of Foreign Affairs; head of the Foreign Relations Office', 'rifts', NULL, '8th level Military Specialist', 8, 'Unprincipled', NULL, NULL, NULL, '{"IQ":15,"ME":19,"MA":18,"PS":14,"PE":15,"Spd":22}', 60, 57, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A skilled orator and diplomat who personally conducted the talks with the NGR and who works out the detail of foreign policy to Lome''s direction. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.143'),
('patrick-oneill', 'General Patrick O''Neill', NULL, 'Minister of Defense; Five-Bar General of the Quebec Army', 'rifts', NULL, '12th level Military Specialist', 12, 'Scrupulous', '71', NULL, NULL, '{"IQ":14,"ME":15,"PS":22,"PE":13}', 66, 40, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Calm and self-assured; a tactician with a clear sense of the price a war exacts from a country.', NULL, NULL, 'A much-campaigned general with heavy sway on the Council, central to readying Quebec for a fight with the Coalition. He helped found the Liberty Reserve and backed new Glitter Boy designs. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.143'),
('erin-tremblay', 'Dr. Erin Tremblay', NULL, 'Minister of Health; head of the Medical Sciences Division', 'rifts', NULL, '9th level Medical Doctor', 9, 'Principled', NULL, NULL, NULL, '{"IQ":18,"MA":17,"PP":15}', 40, 24, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Oversees the health-care technology, law and public medical services of Free Quebec. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.143'),
('robert-fugere', 'Dr. Robert Fugere', NULL, 'Minister of Advanced Medicine; head of the Medical Sciences for human augmentation', 'rifts', NULL, '10th level Cyber-Doc', 10, 'Scrupulous', NULL, NULL, NULL, '{"IQ":21,"ME":20,"PP":18}', 43, 22, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Runs the augmentation sciences, Juicers and bionics above all. He drew up the Shock Trooper Battalions, a humane Juicer programme, and the methods for building cyborg soldiers and returning them to civilian life. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.143'),
('maurice-fraser', 'Maurice Fraser', NULL, 'Minister of Science & Technology', 'rifts', NULL, '10th level Scientist', 10, 'Anarchist', NULL, NULL, NULL, '{"IQ":21,"ME":18,"PB":17}', 39, 22, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Leads the research sectors and advises on technological progress, lately on putting the Triax technology Quebec obtained to use. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.143'),
('micheline-pilot', 'Micheline Pilot', NULL, 'Minister of Industry', 'rifts', NULL, '11th level Operator', 11, 'Unprincipled', NULL, NULL, NULL, '{"IQ":14,"ME":23,"PS":13,"PP":15}', 45, 30, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The Council''s voice on industrial matters. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.143'),
('george-taylor', 'Judge George Taylor', NULL, 'Minister of Justice; head of the Justice Department; retired General', 'rifts', NULL, '10th level Military Specialist, 8th level Judge', 10, 'Scrupulous', '77', NULL, NULL, '{"IQ":14,"ME":18,"MA":19,"PB":17}', 58, 48, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Known as strict yet even-handed.', NULL, NULL, 'A former general who used to run the Quebec Military''s JAG Corps and now enforces and revises the nation''s laws and policies.', 'Rifts World Book 22: Free Quebec p.143'),
('sandra-haley', 'Gen. Sandra Haley', NULL, 'Minister of Intelligence; Commander-in-Chief of le Surete', 'rifts', NULL, '9th level I.S.S. Intel Specter', 9, 'Aberrant', NULL, NULL, NULL, '{"IQ":17,"ME":22,"MA":15,"PS":17,"PP":20,"PE":17,"PB":20,"Spd":14}', 55, 52, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Answers for every intelligence service outside the military, domestic and foreign alike.', 'Rifts World Book 22: Free Quebec p.143');

